functions.callSearch:
function callSearch(element){
		 var reward='';
        if(element=='type'){
        	if($("#type").val()!='-1')
        	$("#channelCode").val($("#type").val());
        	else
        		$("#channelCode").val('');
        }
        else if(element=='rewardType'){
        	$("#channelCode").val("-1");
        	if($("#rewardType").val()!='-1'){
        		reward=$("#rewardType").val();
        		fetchRewardMasterData($("#rewardType").val());
        	}
        	else{
        		fetchRewardMasterData('');
        		$("#channelCode").val('');
        	}

        }
       	var clientID='0';
        if('' == "Y"){
        	clientID=$("#clientId").val();
        }


		var gridObj;
		gridObj = $("#externalAppsSearchGrid");
		gridObj.jqGrid('setGridParam', {
	    	datatype: "json",
	    	page : 1,
	    	mtype: 'POST',
	    	postData : {
	    	extapptype:$("#rewardType").val(),
	    	extid:$("#channelCode").val(),
	    	desc:$("#channelName").val(),
	    	clientId:clientID
	    	},

			url : "jsonExternalAppsSearch?REQ_SEARCH_FLAG=true",
			search : true
		}).trigger('reloadGrid');
	}

